// A small stand-in for reflect-metadata: enough of Reflect.metadata and
// Reflect.getMetadata for TypeScript's __metadata helper.
const store = new WeakMap();
const keyed = (target, key) => {
  let byKey = store.get(target);
  if (!byKey) store.set(target, (byKey = new Map()));
  let entries = byKey.get(key);
  if (!entries) byKey.set(key, (entries = new Map()));
  return entries;
};
Reflect.metadata = (metadataKey, value) => (target, key) => {
  keyed(target, key).set(metadataKey, value);
};
Reflect.getMetadata = (metadataKey, target, key) => keyed(target, key).get(metadataKey);
